fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // Handle edge cases for empty or single-character arrays
    if char_arr.len() <= 1 {
        return true;
    }

    // Get the first character to compare against
    let first_char = char_arr[0];

    // Iterate through the array starting from index 1
    for &ch in &char_arr[1..] {
        if ch != first_char {
            return false; // Found a character that does not match
        }
    }

    true // All characters matched
}